def format(self, *, chain=True, _ctx=None):
    if _ctx is None:
        _ctx = _ExceptionPrintContext()

    output = []
    exc = self
    if chain:
        while exc:
            if exc.__cause__ is not None:
                chained_msg = _cause_message
                chained_exc = exc.__cause__
            elif exc.__context__ is not None and not exc.__suppress_context__:
                chained_msg = _context_message
                chained_exc = exc.__context__
            else:
                chained_msg = None
                chained_exc = None

            output.append((chained_msg, exc))
            exc = chained_exc
    else:
        output.append((None, exc))

    for msg, exc in reversed(output):
        if msg is not None:
            yield from _ctx.emit(msg)
        if exc.exceptions is None:
            if exc.stack:
                yield from _ctx.emit("Traceback (most recent call last):\n")
                yield from _ctx.emit(exc.stack.format())
            yield from _ctx.emit(exc.format_exception_only())
        elif _ctx.exception_group_depth > max_group_depth:
            # exception group, but depth exceeds limit
            yield from _ctx.emit(f"... (max_group_depth is {max_group_depth})\n")
        else:
            # format exception group
            is_toplevel = _ctx.exception_group_depth == 0
            if is_toplevel:
                _ctx.exception_group_depth += 1

            if exc.stack:
                yield from _ctx.emit(
                    "Exception Group Traceback (most recent call last):\n",
                    margin_char="+" if is_toplevel else None,
                )
                yield from _ctx.emit(exc.stack.format())

            yield from _ctx.emit(exc.format_exception_only())
            num_excs = len(exc.exceptions)
            if num_excs <= max_group_width:
                n = num_excs
            else:
                n = max_group_width + 1
            _ctx.need_close = False
            for i in range(n):
                last_exc = i == n - 1
                if last_exc:
                    # The closing frame may be added by a recursive call
                    _ctx.need_close = True

                if max_group_width is not None:
                    truncated = i >= max_group_width
                else:
                    truncated = False
                title = f"{i + 1}" if not truncated else "..."
                yield (
                    _ctx.indent()
                    + ("+-" if i == 0 else "  ")
                    + f"+---------------- {title} ----------------\n"
                )
                _ctx.exception_group_depth += 1
                if not truncated:
                    yield from exc.exceptions[i].format(chain=chain, _ctx=_ctx)
                else:
                    remaining = num_excs - max_group_width
                    plural = "s" if remaining > 1 else ""
                    yield from _ctx.emit(
                        f"and {remaining} more exception{plural}\n"
                    )

                if last_exc and _ctx.need_close:
                    yield _ctx.indent() + "+------------------------------------\n"
                    _ctx.need_close = False
                _ctx.exception_group_depth -= 1

            if is_toplevel:
                assert _ctx.exception_group_depth == 1
                _ctx.exception_group_depth = 0

